-- ===========================================================
-- Title		:	umsp_AbortChangeCharacterRace
-- (author line removed)
-- Create date	:	2016-03-08
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_AbortChangeCharacterRace
(
	@ChangeCharacterRaceKey	BIGINT,
	@ServiceID				BIGINT,
	@GameAccountID			UNIQUEIDENTIFIER,
	@PCID					BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36));
		-- Parameter validity check
		IF	(	ISNULL(@ChangeCharacterRaceKey, -1) <= 0
				OR	(@ServiceID IS NOT NULL AND @ServiceID <= 0)
				OR	(@ServiceID IS NOT NULL AND @GameAccountID IS NULL)
				OR	ISNULL(@PCID, -1) <= 0	)
			RAISERROR(N'invalid parameter, changeCharacterRaceKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
											@ChangeCharacterRaceKey, @ServiceID, @gameAccountIdStr, @PCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			IF	(@ServiceID IS NULL)	BEGIN
				DELETE
				FROM	dbo.ChangeCharacterRace
				WHERE	ChangeCharacterRaceKey	= @ChangeCharacterRaceKey
				AND		ServiceID				IS NULL
				AND		PCID					= @PCID
				AND		ChangeState				= 1;		--	Change Character Race Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such change character race data, changeCharacterRaceKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@ChangeCharacterRaceKey, @ServiceID, @gameAccountIdStr, @PCID);
			END
			ELSE	BEGIN
				DELETE
				FROM	dbo.LobbyService
				WHERE	ServiceID		= @ServiceID
				AND		GameAccountID	= @GameAccountID
				AND		ServiceType		= 8			--	Change Character Race Service
				AND		ServiceState	IN (1, 2);	--	Service Start, Item Consumption Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such lobby service, changeCharacterRaceKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@ChangeCharacterRaceKey, @ServiceID, @gameAccountIdStr, @PCID);
				
				DELETE
				FROM	dbo.ChangeCharacterRace
				WHERE	ChangeCharacterRaceKey	= @ChangeCharacterRaceKey
				AND		ServiceID				= @ServiceID
				AND		PCID					= @PCID
				AND		ChangeState				= 1;		--	Change Character Race Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such change character race data, changeCharacterRaceKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@ChangeCharacterRaceKey, @ServiceID, @gameAccountIdStr, @PCID);
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

