umsp_BlockCharacter.definition:
-- ===========================================================
-- Title		:	umsp_BlockCharacter
-- (author line removed)
-- Create date	:	2012-04-15
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_BlockCharacter
(
	@PCID			BIGINT,
	@BlockType		TINYINT,
	@BlockReason	TINYINT,
	@BlockerName	NVARCHAR(32),
	@BlockComment	NVARCHAR(64),
	@BlockID		BIGINT	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@BlockID = 0;
	
	DECLARE	@INIT_TRANCOUNT			INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS			INT = 0,
			@ERR_FAILURE			INT = 1,
			@ERR_ALREADY_BLOCKED	INT = 2;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@PCID, -1) <= 0
				OR	ISNULL(@BlockType, 0) = 0
				OR	ISNULL(@BlockReason, 0) = 0
				OR	ISNULL(@BlockerName, N'') = N''
				OR	ISNULL(@BlockComment, N'') = N''	)
			RAISERROR(N'invalid parameter, pcId:0x%I64X, blockType:%d, blockReason:%d, blockerName:%s, blockComment:%s', 16, @ERR_FAILURE,
											@PCID, @BlockType, @BlockReason, @BlockerName, @BlockComment);
		
		-- 현재 기간 Block은 고려되지 않았다.
		IF	EXISTS	(	SELECT	1
						FROM	dbo.Block
						WHERE	PCID		= @PCID
						AND		ReleaseTime	IS NULL	)
			RAISERROR(N'already blocked, pcId:0x%I64X', 16, @ERR_ALREADY_BLOCKED, @PCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			INSERT INTO dbo.Block (
				PCID,
				BlockType,
				BlockReason,
				BlockerName,
				BlockComment,
				BlockTime,
				ReleaseReason,
				ReleaserName,
				ReleaseComment,
				ReleaseTime
			)
			VALUES (
				@PCID,
				@BlockType,
				@BlockReason,
				@BlockerName,
				@BlockComment,
				GETDATE(),
				NULL,
				NULL,
				NULL,
				NULL
			);
			SET	@BlockID = SCOPE_IDENTITY();
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
