				AND		RenameState			= 1;	--	Rename Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such rename data, renameKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@RenameKey, @ServiceID, @gameAccountIdStr, @PCID);
			END
			ELSE	BEGIN
				-- 이름 변경의 경우 무조건 완료 처리가 되어야 한다.
				UPDATE	dbo.LobbyService
				SET		ServiceState		= 5,				--	Service Finish
						LastStateUpdateTime	= @currentTime
				WHERE	ServiceID			= @ServiceID
				AND		GameAccountID		= @GameAccountID
				AND		ServiceType			= 3					--	Character Rename Service
				AND		ServiceState		IN (1, 2, 3, 4);	--	Service Start, Item Consumption Try, Task Done, Item Consumption Finish
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such lobby service, renameKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@RenameKey, @ServiceID, @gameAccountIdStr, @PCID);
				
				UPDATE	dbo.CharacterRename
				SET		RenameState			= 2,	--	Rename Completion
						LastStateUpdateTime	= @currentTime
				WHERE	RenameKey			= @RenameKey
				AND		ServiceID			= @ServiceID
				AND		PCID				= @PCID
				AND		RenameState			= 1;	--	Rename Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such rename data, renameKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE,
														@RenameKey, @ServiceID, @gameAccountIdStr, @PCID);
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

