-- ===========================================================
CREATE PROCEDURE dbo.umsp_CompleteSlotAddition
(
	@AdditionKey		BIGINT,
	@ServiceID			BIGINT,
	@GameAccountID		UNIQUEIDENTIFIER,
	@AddedSlotID		UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36)),
				@addedSlotIdStr		NCHAR(36) = CAST(@AddedSlotID AS NCHAR(36));
		-- Parameter validity check
		IF	(	ISNULL(@AdditionKey, -1) <= 0
				OR	(@ServiceID IS NOT NULL AND @ServiceID <= 0)
				OR	@GameAccountID IS NULL
				OR	@AddedSlotID IS NULL	)
			RAISERROR(N'invalid parameter, additionKey:0x%I64X, serviceId:0x%I64X, gameAccountId:%s, addedSlotId:%s', 16, @ERR_FAILURE,
