-- (author line removed)
-- Create date	:	2012-04-11
-- Description	:	캐릭터 삭제
--					처리 순서
--						1. GameDB의 캐릭터 삭제 처리
--						2. LobbyDB의 캐릭터 삭제 처리
-- ===========================================================
CREATE PROCEDURE dbo.umsp_DeleteCharacter
(
	@PCID	BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@PCID, -1) <= 0	)
			RAISERROR(N'invalid parameter, pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			UPDATE	dbo.[Character]
			SET		CharacterState		= 6,		-- Deletion Completion
					LastStateUpdateTime	= GETDATE()
			WHERE	PCID				= @PCID
			AND		CharacterState		IN (2, 3);	-- Creation Completion, Deletion Try
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'no such character, pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
			
			DECLARE	@ret		INT		= @ERR_FAILURE,
					@eventType	TINYINT	= 2;	-- Death
			EXEC	@ret = dbo.usp_RegisterCharacterStory	@PCID, @eventType;
			IF	(@ret != @ERR_SUCCESS)
				RAISERROR(N'failed to register character story, pcId:0x%I64X, eventType:%d', 16, @ERR_FAILURE, @PCID, @eventType);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

