			RAISERROR(N'invalid parameter, scheduleNumber:%I64d', 16, @ERR_FAILURE, @scheduleNumber);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@currentScheduleNumber	BIGINT	= 0;
			
			SELECT	@currentScheduleNumber	= ScheduleNumber
			FROM	dbo.RandomStoreInitializationSchedule
			WITH	(TABLOCKX, INDEX(IX_RandomStoreInitializationSchedule_UniqueCurrentSchedule))
			WHERE	CurrentSchedule			= 1;
			
			IF	(@ScheduleNumber <= @currentScheduleNumber)
				RAISERROR(N'current or past schedule cannot delete, scheduleNumber:%I64d, currentScheduleNumber:%I64d', 16, @ERR_FAILURE, @ScheduleNumber, @currentScheduleNumber);
			
