-- ===========================================================
-- Title		:	umsp_RegisterMileage
-- (author line removed)
-- Create date	:	2014-10-14
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RegisterMileage
	  @MileageName						NVARCHAR(200)
	, @MileageDescription				NVARCHAR(2000)
	, @MileagePolicyID					INT
	, @EffectiveStartTime				DATETIME
	, @EffectiveEndTime					DATETIME
	, @AccumulateEndTime				DATETIME
	, @AccumulateFrequencyType			TINYINT
	, @AccumulateFrequency				TINYINT
	, @MileageVirtualCurrencyID			SMALLINT
	, @MileageVirtualCurrencyAmount		BIGINT
	, @MileageVirtualCurrencyExpireTime	DATETIME
	, @AccumulateMinuteLimitPerDay		SMALLINT
	, @AccumulateLimitStandardHour		TIME(0)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		DECLARE @effectiveStartTimeStr					NCHAR(23)	= N'',
				@effectiveEndTimeStr					NCHAR(23)	= N'',
				@accumulateEndTimeStr					NCHAR(23)	= N'',
				@mileageVirtualCurrencyExpireTimeStr	NCHAR(23)	= N'',
				@accumulateLimitStandardHourStr			NCHAR(8)	= N'';

		-- Parameter validity check
		IF	(		ISNULL(@MileageName						, N'')				=  N''
				OR	ISNULL(@MileageDescription				, N'')				=  N''
				OR	ISNULL(@MileagePolicyID					, -1 )				<= 0
				OR	ISNULL(@EffectiveStartTime				, N'1970-01-01')	=  N'1970-01-01'
				OR	ISNULL(@EffectiveEndTime				, N'1970-01-01')	=  N'1970-01-01'
				OR	ISNULL(@AccumulateEndTime				, N'1970-01-01')	=  N'1970-01-01'
				OR	ISNULL(@AccumulateFrequencyType			, 0)				<= 0
				OR	ISNULL(@AccumulateFrequency				, 0)				<= 0
				OR	ISNULL(@MileageVirtualCurrencyID		, -1)				<= 0
				OR	ISNULL(@MileageVirtualCurrencyAmount	, -1)				<= 0
				OR	ISNULL(@MileageVirtualCurrencyExpireTime, N'1970-01-01')	=  N'1970-01-01'
				OR	@EffectiveStartTime											>= @EffectiveEndTime
				OR	@AccumulateEndTime											>  @EffectiveEndTime
				OR	(	@AccumulateMinuteLimitPerDay							IS NOT NULL
						AND @AccumulateMinuteLimitPerDay						<= 0)					
				OR	(	@AccumulateMinuteLimitPerDay							IS NOT NULL
						AND @AccumulateLimitStandardHour						IS NULL)					)
		BEGIN
			SELECT	@effectiveStartTimeStr					= CONVERT(NCHAR(23), @EffectiveStartTime, 121),
					@effectiveEndTimeStr					= CONVERT(NCHAR(23), @EffectiveEndTime, 121),
					@accumulateEndTimeStr					= CONVERT(NCHAR(23), @AccumulateEndTime, 121),
					@mileageVirtualCurrencyExpireTimeStr	= CONVERT(NCHAR(23), @MileageVirtualCurrencyExpireTime, 121),
					@accumulateLimitStandardHourStr			= CONVERT(NCHAR(8),  @AccumulateLimitStandardHour, 121);
			RAISERROR(	N'invalid initial parameter, mileageName:%s, mileageDescription:%s, mileagePolicyId:%d, effectiveStartTime:%s, effectiveEndTime:%s, accumulateEndTime:%s, accumulateFrequencyType:%d, accumulateFrequency:%d, mileageVirtualCurrencyId:%d, mileageVirtualCurrencyAmount:0x%I64X, mileageVirtualCurrencyExpireTime:%s, accumulateMinuteLimitPerDay:%d, accumulateLimitStandardHour:%s',
						16, @ERR_FAILURE,
						@MileageName, @MileageDescription, @MileagePolicyID, @effectiveStartTimeStr, @effectiveEndTimeStr, @accumulateEndTimeStr, @AccumulateFrequencyType, @AccumulateFrequency, @MileageVirtualCurrencyID, @MileageVirtualCurrencyAmount, @mileageVirtualCurrencyExpireTimeStr, @AccumulateMinuteLimitPerDay, @accumulateLimitStandardHourStr);
		END

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN

		BEGIN
			DECLARE @duplicateMileageID	INT = 0,
					@rowcount			INT = 0,
					@mileageID			INT = 0;
			
			MERGE	dbo.Mileage	AS Target
			USING	(VALUES(@MileagePolicyID, @EffectiveStartTime)) AS Source(MileagePolicyID, EffectiveStartTime)
					ON Target.MileagePolicyID = Source.MileagePolicyID AND Target.EffectiveStartTime <= Source.EffectiveStartTime AND Target.EffectiveEndTime > Source.EffectiveStartTime AND Target.EndTime IS NULL
			WHEN MATCHED THEN
				UPDATE
				SET @duplicateMileageID = Target.MileageID
			WHEN NOT MATCHED THEN
				INSERT	(MileageName, MileageDescription, MileagePolicyID, EffectiveStartTime, EffectiveEndTime, AccumulateEndTime, AccumulateFrequencyType,AccumulateFrequency,
						 MileageVirtualCurrencyID, MileageVirtualCurrencyAmount, MileageVirtualCurrencyExpireTime, IsActivated, FirstActivatedTime, AccumulateMinuteLimitPerDay, AccumulateLimitStandardHour, RegistrationTime)
				VALUES	(@MileageName, @MileageDescription, @MileagePolicyID, @EffectiveStartTime, @EffectiveEndTime, @AccumulateEndTime, @AccumulateFrequencyType, @AccumulateFrequency,
						 @MileageVirtualCurrencyID, @MileageVirtualCurrencyAmount, @MileageVirtualCurrencyExpireTime, 0, NULL, @AccumulateMinuteLimitPerDay, @AccumulateLimitStandardHour, GETDATE());
			SELECT @rowcount = @@ROWCOUNT, @mileageID = SCOPE_IDENTITY()
			IF	(@rowcount != 1 OR @mileageID IS NULL OR @mileageID < 1 OR @duplicateMileageID > 0)
			BEGIN
				SELECT	@effectiveStartTimeStr					= CONVERT(NCHAR(23), @EffectiveStartTime, 121),
						@effectiveEndTimeStr					= CONVERT(NCHAR(23), @EffectiveEndTime, 121),
						@accumulateEndTimeStr					= CONVERT(NCHAR(23), @AccumulateEndTime, 121),
						@mileageVirtualCurrencyExpireTimeStr	= CONVERT(NCHAR(23), @MileageVirtualCurrencyExpireTime, 121),
						@accumulateLimitStandardHourStr			= CONVERT(NCHAR(8),  @AccumulateLimitStandardHour, 121);;
				RAISERROR(	N'failed to register mileage, mileageName:%s, mileageDescription:%s, mileagePolicyId:%d, effectiveStartTime:%s, effectiveEndTime:%s, accumulateEndTime:%s, accumulateFrequencyType:%d, accumulateFrequency:%d, mileageVirtualCurrencyId:%d, mileageVirtualCurrencyAmount:0x%I64X, mileageVirtualCurrencyExpireTime:%s, accumulateMinuteLimitPerDay:%d, accumulateLimitStandardHour:%s, duplicateMileageId:%d',
							16, @ERR_FAILURE,
							@MileageName, @MileageDescription, @MileagePolicyID, @effectiveStartTimeStr, @effectiveEndTimeStr, @accumulateEndTimeStr, @AccumulateFrequencyType, @AccumulateFrequency, @MileageVirtualCurrencyID, @MileageVirtualCurrencyAmount, @mileageVirtualCurrencyExpireTimeStr, @AccumulateMinuteLimitPerDay, @accumulateLimitStandardHourStr, @duplicateMileageID);
			END
		END

		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

