-- ===========================================================
-- Title		:	umsp_RegisterMileageFeverTime
-- (author line removed)
-- Create date	:	2014-10-14
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RegisterMileageFeverTime
	  @MileageID					INT
	, @MileageFeverTimeName			NVARCHAR(200)
	, @EffectiveStartTime			DATETIME
	, @EffectiveEndTime				DATETIME
	, @FeverVirtualCurrencyAmount	BIGINT
	, @RepeatType					TINYINT
	, @RepeatStartTime				TIME(0)
	, @RepeatDuration				INT
	, @DayOfWeek					BINARY(1)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		DECLARE	@effectiveStartTimeStr	NVARCHAR(23)	= N'',
				@effectiveEndTimeStr	NVARCHAR(23)	= N'',
				@repeatStartTimeStr		NVARCHAR(8)		= N'';

		-- Parameter validity check
		IF	(		ISNULL(@MileageID					, -1)			<= 0
				OR	ISNULL(@MileageFeverTimeName		, N'')			=  N''
				OR	ISNULL(@EffectiveStartTime			, '1970-01-01')	=  '1970-01-01'
				OR	ISNULL(@EffectiveEndTime			, '1970-01-01')	=  '1970-01-01'
				OR	ISNULL(@FeverVirtualCurrencyAmount	, -1)			<= 0
				OR	ISNULL(@RepeatType					, -1)			<= 0
				OR	@EffectiveStartTime									>= @EffectiveEndTime
				OR	@RepeatType											NOT IN(1, 2, 3)
				OR	(@RepeatType = 2 AND (@RepeatStartTime IS NULL OR ISNULL(@RepeatDuration, -1) <= 0))
				OR	(@RepeatType = 3 AND (@RepeatStartTime IS NULL OR ISNULL(@RepeatDuration, -1) <= 0 OR @DayOfWeek = 0x00))	)
		BEGIN
			SELECT	@effectiveStartTimeStr	= CAST(@EffectiveStartTime	AS NVARCHAR(23)),
					@effectiveEndTimeStr	= CAST(@EffectiveEndTime	AS NVARCHAR(23)),
					@repeatStartTimeStr		= CAST(@RepeatStartTime		AS NVARCHAR(8));
			RAISERROR(	N'invalid parameter, mileageId:%d, mileageFeverTimeName:%s, effectiveStartTime:%s, effectiveEndTime:%s, feverVirtualCurrencyAmount:%d, repeatType:%d, repeatStartTime:%s, repeatDuration:%d, daysOfWeek:0x%X',
						16, @ERR_FAILURE, 
						@MileageID, @MileageFeverTimeName, @effectiveStartTimeStr, @effectiveEndTimeStr, @FeverVirtualCurrencyAmount, @RepeatType, @repeatStartTimeStr, @RepeatDuration, @DayOfWeek);
		END

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			INSERT	dbo.MileageFeverTime
					(MileageID, MileageFeverTimeName, EffectiveStartTime, EffectiveEndTime, FeverVirtualCurrencyAmount, IsActivated, FirstActivatedTime, RepeatType, RepeatStartTime, RepeatDuration, [DayOfWeek])
			VALUES	(@MileageID, @MileageFeverTimeName, @EffectiveStartTime, @EffectiveEndTime, @FeverVirtualCurrencyAmount, 0, NULL, @RepeatType, @RepeatStartTime, @RepeatDuration, @DayOfWeek);
			IF	(@@ROWCOUNT != 1)
			BEGIN
				SELECT	@effectiveStartTimeStr	= CAST(@EffectiveStartTime	AS NVARCHAR(23)),
						@effectiveEndTimeStr	= CAST(@EffectiveEndTime	AS NVARCHAR(23)),
						@repeatStartTimeStr		= CAST(@RepeatStartTime	AS NVARCHAR(8));
				RAISERROR(	N'invalid parameter, mileageId:%d, mileageFeverTimeName:%s, effectiveStartTime:%s, effectiveEndTime:%s, feverVirtualCurrencyAmount:%d, repeatType:%d, repeatStartTime:%s, repeatDuration:%d, daysOfWeek:0x%X',
							16, @ERR_FAILURE, 
							@MileageID, @MileageFeverTimeName, @effectiveStartTimeStr, @effectiveEndTimeStr, @FeverVirtualCurrencyAmount, @RepeatType, @repeatStartTimeStr, @RepeatDuration, @DayOfWeek);
			END
		END

		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

