-- ===========================================================
-- Title		:	umsp_RegisterRandomStoreInitializationSchedule
-- (author line removed)
-- Create date	:	2014-03-20
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RegisterRandomStoreInitializationSchedule
(
	@ScheduleStartTime	DATETIME,
	@InitSlotCount			BIT,
	@InitPremiumDrawCount	BIT,
	@ScheduleNumber		BIGINT		OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@ScheduleNumber	= 0;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		DECLARE	@scheduleStartTimeStr	NVARCHAR(19)	= CONVERT(NVARCHAR(19), @ScheduleStartTime, 120);
		IF	(	@ScheduleStartTime			IS NULL	
				OR	@InitSlotCount			IS NULL		
				OR	@InitPremiumDrawCount	IS NULL
				OR	@ScheduleStartTime <= GETDATE()			
			)
			RAISERROR(N'invalid parameter, scheduleStartTime:%s', 16, @ERR_FAILURE, @scheduleStartTimeStr);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			IF	EXISTS	(
							SELECT	1
							FROM	dbo.RandomStoreInitializationSchedule
							WITH	(TABLOCKX, INDEX(UK_RandomStoreInitializationSchedule_ScheduleStartTime))
							WHERE	ScheduleStartTime	> @ScheduleStartTime
						)
				RAISERROR(N'schedule start time is not last time, scheduleStartTime:%s', 16, @ERR_FAILURE, @scheduleStartTimeStr);
			
			INSERT INTO dbo.RandomStoreInitializationSchedule (
				ScheduleStartTime,
				CurrentSchedule,
				InitSlotCount,
				InitPremiumDrawCount
			)
			VALUES (
				@ScheduleStartTime,
				0,
				@InitSlotCount,
				@InitPremiumDrawCount
			);
			SET	@ScheduleNumber = SCOPE_IDENTITY();
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

umsp_RenameCharacter.definition:
-- ===========================================================
-- Title		:	umsp_RenameCharacter
-- (author line removed)
-- Create date	:	2012-04-10
-- Description	:	캐릭터 이름 변경
--					처리 순서
--						1. LobbyDB의 캐릭터 이름 변경 처리
--						2. GameDB의 캐릭터 이름 변경 처리
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RenameCharacter
(
	@PCID					BIGINT,
	@NewCharacterName		NVARCHAR(32),
	@ReuseLimitDuration		INT,
	@OldCharacterName		NVARCHAR(32)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@OldCharacterName	= N'';
	
	DECLARE	@INIT_TRANCOUNT					INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS					INT = 0,
			@ERR_FAILURE					INT = 1,
			@ERR_DUPLICATED_CHARACTER_NAME	INT = 2,
			@ERR_LIMITED_CHARACTER_NAME		INT = 3;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@PCID, -1) <= 0
				OR	ISNULL(@NewCharacterName, N'') = N''
				OR	ISNULL(@ReuseLimitDuration, -1) < 0	)
			RAISERROR(N'invalid parameter, pcId:0x%I64X, newCharacterName:%s, reuseLimitDuration:%d', 16, @ERR_FAILURE,
											@PCID, @NewCharacterName, @ReuseLimitDuration);
		
		DECLARE	@ret	INT = @ERR_FAILURE;
		EXEC	@ret = dbo.usp_CheckValidityOfCharacterName @NewCharacterName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'invalid character name, newCharacterName:%s', 16, @ERR_FAILURE, @NewCharacterName);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@oldPureCharacterName	NVARCHAR(32)	= NULL;
			DECLARE	@registrationTime		DATETIME		= GETDATE();
			DECLARE	@resueLimitTime			DATETIME		= DATEADD(SECOND, @ReuseLimitDuration, @registrationTime);
			
			UPDATE	dbo.[Character]
			SET		@OldCharacterName		= CharacterName,
					@oldPureCharacterName	= PureCharacterName,
					CharacterName			= @NewCharacterName,
					PureCharacterName		= dbo.ufn_GetPureName(@NewCharacterName)
			WHERE	PCID			= @PCID
			AND		CharacterState	= 2;	-- Creation Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'there is no such character, pcId:0x%I64X, newCharacterName:%s, reuseLimitDuration:%d', 16, @ERR_FAILURE, @PCID, @NewCharacterName, @ReuseLimitDuration);
			
			INSERT INTO dbo.CharacterRename(
				ServiceID,
				PCID,
				OldCharacterName,
				OldPureCharacterName,
				NewCharacterName,
				NewPureCharacterName,
				RenameState,
				RegistrationTime,
				LastStateUpdateTime,
				ReuseLimitTime
			)
			VALUES (
				NULL,
				@PCID,
				@OldCharacterName,
				@oldPureCharacterName,
				@NewCharacterName,
				dbo.ufn_GetPureName(@NewCharacterName),
				2,	-- Rename Completion
				@registrationTime,
				@registrationTime,
				@resueLimitTime
			);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
			ELSE	BEGIN
				IF	(@ERR_PROCEDURE = N'usp_CheckValidityOfCharacterName')	BEGIN
					SELECT	@ERR_CODE	=	CASE	@ERR_STATE	WHEN	2	THEN	@ERR_DUPLICATED_CHARACTER_NAME
																WHEN	3	THEN	@ERR_LIMITED_CHARACTER_NAME
																ELSE				@ERR_FAILURE	END
				END
			END
		END
		ELSE IF (@ERR_NUMBER = 2601)
			SET	@ERR_CODE = @ERR_DUPLICATED_CHARACTER_NAME;
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

umsp_RenameGuild.definition:
-- ===========================================================
-- Title		:	umsp_RenameGuild
-- (author line removed)
-- Create date	:	2014-06-02
-- Description	:	문파 이름 변경
--					처리 순서
--						1. LobbyDB의 문파 이름 변경 처리
--						2. GameDB의 문파 이름 변경 처리
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RenameGuild
(
	@GuildID				BIGINT,
	@NewGuildName			NVARCHAR(32),
	@ReuseLimitDuration		INT,
	@OldGuildName			NVARCHAR(32)	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@OldGuildName	= N'';
	
	DECLARE	@INIT_TRANCOUNT					INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS					INT = 0,
			@ERR_FAILURE					INT = 1,
			@ERR_DUPLICATED_GUILD_NAME		INT = 2,
			@ERR_LIMITED_GUILD_NAME			INT = 3,
			@ERR_ALREADY_IN_TRY_STATE		INT = 4;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'rename-guild; invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@GuildID, -1) <= 0
				OR	ISNULL(@NewGuildName, N'') = N''
				OR	ISNULL(@ReuseLimitDuration, -1) < 0	)
			RAISERROR(N'rename-guild; invalid parameter, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_FAILURE,
											@GuildID, @NewGuildName, @ReuseLimitDuration);
		
		DECLARE	@ret	INT = @ERR_FAILURE;
		EXEC	@ret = dbo.usp_CheckValidityOfGuildName @NewGuildName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'rename-guild; invalid guild name, new-guild-name:%s', 16, @ERR_FAILURE, @NewGuildName);
		
		IF	EXISTS	(	SELECT	1
						FROM	dbo.GuildRename
						WHERE	GuildID		= @GuildID
						AND		RenameState	= 1		-- Rename Try
					)
			RAISERROR(N'rename-guild; already in try state, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_ALREADY_IN_TRY_STATE, @GuildID, @NewGuildName, @ReuseLimitDuration);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@oldPureGuildName	NVARCHAR(32)	= NULL;
			DECLARE	@registrationTime	DATETIME		= GETDATE();
			DECLARE	@resueLimitTime		DATETIME		= DATEADD(SECOND, @ReuseLimitDuration, @registrationTime);
			
			UPDATE	dbo.GuildRegistry
			SET		@OldGuildName		= GuildName,
					@oldPureGuildName	= PureGuildName,
					GuildName			= @NewGuildName,
					PureGuildName		= dbo.ufn_GetPureName(@NewGuildName)
			WHERE	GuildID				= @GuildID
			AND		GuildState			= 2;	-- Creation Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'rename-guild; there is no such guild, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_FAILURE, @GuildID, @NewGuildName, @ReuseLimitDuration);
			
			INSERT INTO dbo.GuildRename(
				GuildID,
				RenameGuildType,
				OldGuildName,
				OldPureGuildName,
				NewGuildName,
				NewPureGuildName,
				RenameState,
				RegistrationTime,
				LastStateUpdateTime,
				ReuseLimitTime
			)
			VALUES (
				@GuildID,
				0,		-- RENAMEGUILDTYPE_NONE (By Management)
				@OldGuildName,
				@oldPureGuildName,
				@NewGuildName,
				dbo.ufn_GetPureName(@NewGuildName),
				2,	-- Rename Completion
				@registrationTime,
				@registrationTime,
				@resueLimitTime
			);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
			ELSE	BEGIN
				IF	(@ERR_PROCEDURE = N'usp_CheckValidityOfGuildName')	BEGIN
					SELECT	@ERR_CODE	=	CASE	@ERR_STATE	WHEN	2	THEN	@ERR_DUPLICATED_GUILD_NAME
																WHEN	3	THEN	@ERR_LIMITED_GUILD_NAME
																ELSE				@ERR_FAILURE	END
				END
			END
		END
		ELSE IF (@ERR_NUMBER = 2601)
			SET	@ERR_CODE = @ERR_DUPLICATED_GUILD_NAME;
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

umsp_RestorationDeletedCharacter.definition:
-- ===========================================================
-- Title		:	umsp_RestorationDeletedCharacter
-- (author line removed)
-- Create date	:	2016-01-05
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.umsp_RestorationDeletedCharacter
(
	  @PCID					BIGINT,
	  @NewCharacterName		NVARCHAR(32),
	  @ReuseLimitDuration	INT,
	  @NewSlotID			UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT				INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS				INT = 0,
			@ERR_FAILURE				INT = 1,
			@ERR_PCSTATE_REGISTRAION	INT = 2;
	
	BEGIN TRY
		DECLARE @newSlotIDStr NCHAR(36) = N'';
		
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(		ISNULL(@PCID, -1)				<= 0
				OR	ISNULL(@NewCharacterName, N'')	= N''
				OR	ISNULL(@ReuseLimitDuration, -1)	<  0
				OR	@NewSlotID						IS NULL
			)
		BEGIN
			SET @newSlotIDStr = CAST(@NewSlotID AS NCHAR(36));
			RAISERROR(N'invalid parameter, pcId:%I64d, newCharacterName:%s, reuseLimitDuration:%d, newSlotId:%s', 16, @ERR_FAILURE, @PCID, @NewCharacterName, @ReuseLimitDuration, @newSlotIDStr);
		END
		
		IF	(	EXISTS(SELECT TOP 1 1 FROM dbo.[Character] WITH(READUNCOMMITTED) WHERE PCID = @PCID AND CharacterState = 2)
			)
		BEGIN
			SET @newSlotIDStr = CAST(@NewSlotID AS NCHAR(36));
			RAISERROR(N'invalid character state, pcId:%I64d, newCharacterName:%s, reuseLimitDuration:%d, newSlotId:%s', 16, @ERR_PCSTATE_REGISTRAION, @PCID, @NewCharacterName, @ReuseLimitDuration, @newSlotIDStr);
		END
		
		DECLARE	@ret	INT = @ERR_FAILURE;
		EXEC	@ret = dbo.usp_CheckValidityOfCharacterName @NewCharacterName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'invalid character name, newCharacterName:%s', 16, @ERR_FAILURE, @NewCharacterName);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@oldCharacterName		NVARCHAR(32)		= N'',
					@oldPureCharacterName	NVARCHAR(32)		= N'',
					@registrationTime		DATETIME			= GETDATE(),
					@gameAccountID			UNIQUEIDENTIFIER;
			DECLARE	@resueLimitTime			DATETIME			= DATEADD(SECOND, @ReuseLimitDuration, @registrationTime),
					@lastStateUpdateTime	DATETIME			= @registrationTime;

			UPDATE	dbo.[Character]
			SET		@gameAccountID			= GameAccountID,
					@oldCharacterName		= CharacterName,
					@oldPureCharacterName	= PureCharacterName,
					CharacterName			= @NewCharacterName,
					PureCharacterName		= dbo.ufn_GetPureName(@NewCharacterName),
					SlotID					= @NewSlotID,
					CharacterState			= 2,	-- Creation Completion
					LastStateUpdateTime		= @lastStateUpdateTime,
					DeletionDelayTime		= NULL
			WHERE	PCID			= @PCID
			AND		CharacterState	= 6;	
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'there is no such character, pcId:0x%I64X, newCharacterName:%s', 16, @ERR_FAILURE, @PCID, @NewCharacterName);

			INSERT	dbo.CharacterRename
					(ServiceID, PCID, OldCharacterName, OldPureCharacterName, NewCharacterName, NewPureCharacterName,
					 RenameState, RegistrationTime, LastStateUpdateTime, ReuseLimitTime)
			VALUES
					(NULL, @PCID, @oldCharacterName, @oldPureCharacterName, @NewCharacterName, dbo.ufn_GetPureName(@NewCharacterName),
					 2, @registrationTime, @registrationTime, @resueLimitTime);

			IF	EXISTS(	SELECT	TOP 1 1
						FROM	dbo.[Character]
						WITH	(READUNCOMMITTED, INDEX(IX_Character_GameAccountID_CharacterState))
						WHERE	GameAccountID = @gameAccountID AND SlotID = @NewSlotID AND PCID != @PCID AND CharacterState != 6)
			BEGIN
				SET @newSlotIDStr = CAST(@NewSlotID AS NCHAR(36));
				RAISERROR(N'already exists slotId, pcId:0x%I64X, newCharacterName:%s, newSlotId:%s', 16, @ERR_FAILURE, @PCID, @NewCharacterName, @newSlotIDStr);
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

