CREATE PROCEDURE dbo.umsp_RetrieveMileage
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		BEGIN
			SELECT	Mileage.MileageID, Mileage.MileageName, Mileage.MileageDescription, MileagePolicy.MileagePolicyName, Mileage.EffectiveStartTime,
					Mileage.EffectiveEndTime, Mileage.EndTime, Mileage.AccumulateEndTime, Mileage.AccumulateFrequencyType,
					Mileage.AccumulateFrequency, MileageCurrency.VirtualCurrencyName, Mileage.MileageVirtualCurrencyAmount,
					Mileage.MileageVirtualCurrencyExpireTime, Mileage.IsActivated, Mileage.FirstActivatedTime,
					Mileage.AccumulateMinuteLimitPerDay, Mileage.AccumulateLimitStandardHour, Mileage.RegistrationTime
			FROM	dbo.Mileage WITH(READUNCOMMITTED)
				INNER JOIN	dbo.MileagePolicy WITH(READUNCOMMITTED, INDEX(PK_MileagePolicy))
						ON	Mileage.MileagePolicyID = MileagePolicy.MileagePolicyID
				INNER JOIN	dbo.MileageCurrency WITH(READUNCOMMITTED, INDEX(PK_MileageCurrency))
						ON	Mileage.MileageVirtualCurrencyID = MileageCurrency.VirtualCurrencyID
			ORDER BY Mileage.MileageID DESC;
		END	

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
