-- ===========================================================
CREATE PROCEDURE dbo.umsp_RetryMileageDeposit
(
	@MileageDepositID	BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@MileageDepositID, -1) <= 0	)
			RAISERROR(N'invalid parameter, mileageDepositId:0x%I64X', 16, @ERR_FAILURE, @MileageDepositID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			UPDATE	dbo.MileageDeposit
			SET		DepositState					= 3,	--	Retry
					DepositStateModificationTime	= GETDATE()
			WHERE	MileageDepositID				= @MileageDepositID
			AND		DepositState					= 2;	--	Failed
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to retry mileage deposit, no such deposit, mileageDepositId:0x%I64X', 16, @ERR_FAILURE, @MileageDepositID);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
