CREATE PROCEDURE dbo.usp_CancelRenameGuild
(
	@RenameKey		BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'rename-guild; invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@RenameKey, -1) <= 0	)
			RAISERROR(N'rename-guild; invalid parameter, rename-key:0x%I64x', 16, @ERR_FAILURE, @RenameKey);
		
		DECLARE	@guildID			BIGINT,
				@oldGuildName		NVARCHAR(32),
				@oldPureGuildName	NVARCHAR(32);

		
		SELECT	@guildID			= GuildID,
				@oldGuildName		= OldGuildName,
				@oldPureGuildName	= OldPureGuildName
		FROM	dbo.GuildRename
		WHERE	RenameKey	= @RenameKey
		AND		RenameState	= 1;	-- Rename Try
		IF	(@@ROWCOUNT != 1)
			RAISERROR(N'rename-guild; no such rename data, rename-key:0x%I64x', 16, @ERR_FAILURE, @RenameKey);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			UPDATE	dbo.GuildRegistry
			SET		GuildName		= @oldGuildName,
					PureGuildName	= @oldPureGuildName
			WHERE	GuildID			= @guildID
			AND		GuildState		= 2;	-- Creation Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'rename-guild; no such guild, guild-id:0x%I64x', 16, @ERR_FAILURE, @guildID);
			
