				RAISERROR(N'rename-guild; no such rename data, rename-key:0x%I64x, guild-id:0x%I64x', 16, @ERR_FAILURE, @RenameKey, @guildID);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
