-- ===========================================================
-- Title		:	usp_CharacterMove_UpdateWorldID
-- (author line removed)
-- Create date	:	2016-02-24
-- Description	:	[캐릭터 서버이동] 이동 후 처리
-- ===========================================================
CREATE PROCEDURE usp_CharacterMove_UpdateWorldID
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, 
											@INIT_TRANCOUNT);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN

			UPDATE dbo.Character
			SET WorldID = mov.NewWorldID
			FROM CharacterMove AS mov
			WHERE Character.PCID = mov.PCID
				AND mov.MoveState = 7
				
			-- 이동완료
			UPDATE dbo.CharacterMove
			SET MoveState = 8
			WHERE MoveState = 7
			
			-- 시스템에러(-8,16384) 처리
			UPDATE dbo.CharacterMove
			SET 
				MoveState = -8, 
				Errors = 16384
			WHERE MoveState IN (1,2,3,4,5)
			
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
