-- ===========================================================
CREATE PROCEDURE dbo.usp_CheckValidityOfCharacterName
(
	@CharacterName	NVARCHAR(32)
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT					INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS					INT = 0,
			@ERR_FAILURE					INT = 1,
			@ERR_DUPLICATED_CHARACTER_NAME	INT = 2,
			@ERR_LIMITED_CHARACTER_NAME		INT = 3;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@CharacterName, N'') = N''	)
			RAISERROR(N'invalid parameter, characterName:%s', 16, @ERR_FAILURE, @CharacterName);
		
		BEGIN
			DECLARE	@pureCharacterName	NVARCHAR(32) = dbo.ufn_GetPureName(@CharacterName);
			
			-- Check CharacterName
			IF	EXISTS	(	SELECT	1
							FROM	dbo.[Character]
							WITH	(INDEX(IX_Character_UniqueCharacterName))
							WHERE	PureCharacterName	= @pureCharacterName
							AND		CharacterState		!= 6	)	-- Deletion Completion
				RAISERROR(N'duplicated character name, characterName:%s, pureCharacterName:%s', 16, @ERR_DUPLICATED_CHARACTER_NAME, @CharacterName, @pureCharacterName);
			
			IF	EXISTS	(	SELECT	1
							FROM	dbo.CharacterRename
							WITH	(INDEX(IX_CharacterRename_LimitedCharacterName))
							WHERE	OldPureCharacterName	= @pureCharacterName
							AND		(
										(	RenameState	= 1	)									-- Rename Try
										OR
										(	RenameState	= 2	AND	ReuseLimitTime	> GETDATE()	)	-- Rename Completion
									)
						)
				RAISERROR(N'limited character name, characterName:%s, pureCharacterName:%s', 16, @ERR_LIMITED_CHARACTER_NAME, @CharacterName, @pureCharacterName);
		END
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

