CREATE PROCEDURE dbo.usp_DeleteGuild
(
	@GuildID				BIGINT,
	@ReuseLimitDuration		INT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@GuildID, -1) <= 0
				OR	ISNULL(@ReuseLimitDuration, -1) <= 0	)
			RAISERROR(N'invalid parameter, guildId:0x%I64X, reuseLimitDuration:%d', 16, @ERR_FAILURE, @GuildID, @ReuseLimitDuration);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@currentTime	DATETIME = GETDATE();		
			DECLARE	@reuseLimitTime	DATETIME = DATEADD(SECOND, @ReuseLimitDuration, @currentTime);
			
			UPDATE	dbo.GuildRegistry
			SET		GuildState			= 3,	-- Deletion Completion
					LastStateUpdateTime	= @currentTime,
					ReuseLimitTime		= @reuseLimitTime
			WHERE	GuildID				= @GuildID
			AND		GuildState			= 2;	-- Creation Completion
			IF (@@ROWCOUNT != 1)
				RAISERROR(N'no such guild, guildId:0x%I64X', 16, @ERR_FAILURE, @GuildID);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
