-- ===========================================================
CREATE PROCEDURE dbo.usp_EraseCharacterData
(
	@GameAccountID	UNIQUEIDENTIFIER,
	@PCID			BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36));
		IF	(	@GameAccountID IS NULL
				OR	ISNULL(@PCID, -1) <= 0	)
			RAISERROR(N'invalid parameter, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE, @gameAccountIdStr, @PCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			-- Character
			DELETE
			FROM	dbo.Block
			WHERE	PCID	= @PCID;
			
			DELETE
			FROM	dbo.CharacterLifeStory
			WHERE	PCID	= @PCID;
			
			DELETE
			FROM	dbo.CharacterRightHistory
			WHERE	PCID	= @PCID;
			
			DELETE
			FROM	dbo.CharacterData
			WHERE	PCID	= @PCID;
			
			DELETE
			FROM	dbo.[Character]
			WHERE	PCID			= @PCID
			AND		GameAccountID	= @GameAccountID;
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to erase character, gameAccountId:%s, pcId:0x%I64X', 16, @ERR_FAILURE, @gameAccountIdStr, @PCID);
			
			-- GameAccount
			DELETE
			FROM	dbo.GameAccountRightHistory
			WHERE	GameAccountID	= @GameAccountID;
			
			DELETE
			FROM	dbo.GameAccount
			WHERE	GameAccountID	= @GameAccountID;
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
