-- ===========================================================
-- Title		:	usp_ExtendJumpingCharacterCreationQuota
-- (author line removed)
-- Create date	:	2016-01-06
-- Description	:	
-- ===========================================================
CREATE PROC dbo.usp_ExtendJumpingCharacterCreationQuota
(
	  @GameAccountID		UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		DECLARE	@gameAccountIdStr	NCHAR(36) = N'';
		
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		-- Parameter validity check
		IF	(	@GameAccountID IS NULL	)	BEGIN
			SET	@gameAccountIdStr = CAST(@GameAccountID AS NCHAR(36));
			RAISERROR(N'invalid parameter, gameAccountId:%s', 16, @ERR_FAILURE, @gameAccountIdStr);
		END

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN

		BEGIN
			MERGE	dbo.JumpingCharacterCreationQuota	AS Target
			USING	(VALUES(@GameAccountID, 1))			AS Source(GameAccountID, CreationQuota)
			ON		Target.GameAccountID = Source.GameAccountID
			WHEN MATCHED THEN
				UPDATE SET CreationQuota += Source.CreationQuota
			WHEN NOT MATCHED THEN
				INSERT (GameAccountID, CreationQuota, CreationCount)
				VALUES (Source.GameAccountID, Source.CreationQuota, 0);
			IF	(@@ROWCOUNT != 1)
			BEGIN
				SET	@gameAccountIdStr = CAST(@GameAccountID AS NCHAR(36));
				RAISERROR(N'failed to extend jumping character creation quota, gameAccountId:%s', 16, @ERR_FAILURE, @gameAccountIdStr);
			END
		END

		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

