				OR	ISNULL(@DeliveryID, -1) <= 0
				OR	ISNULL(@PostID, -1) <= 0	)
			RAISERROR(N'invalid parameter, escrowId:0x%I64X, deliveryId:0x%I64X, postId:0x%I64X', 16, @ERR_FAILURE, @EscrowID, @DeliveryID, @PostID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@currentTime	DATETIME	= GETDATE();
			
			UPDATE	dbo.AuctionEscrow
			SET		EscrowState			=	CASE	EscrowState
												WHEN	3	THEN	4	--	Restoration Completion
												ELSE	EscrowState
											END,
					LastStateUpdateTime	=	CASE	EscrowState
												WHEN	3	THEN	@currentTime
												ELSE	LastStateUpdateTime
											END
			WHERE	EscrowID			=	@EscrowID
			AND		EscrowState			IN	(3, 4);		--	Restoration Ready, Restoration Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to update auction escrow state; there is no such escrow id or invalid escrow state, escrowId:0x%I64X, deliveryId:0x%I64X, postId:0x%I64X', 16, @ERR_FAILURE,
																														@EscrowID, @DeliveryID, @PostID);
			
			UPDATE	dbo.AuctionDelivery
			SET		PostID			=	CASE
											WHEN	PostID IS NULL	THEN	@PostID
											ELSE	PostID
										END,
					LastUpdateTime	=	CASE
											WHEN	PostID IS NULL	THEN	@currentTime
											ELSE	LastUpdateTime
										END
			WHERE	DeliveryID		=	@DeliveryID
			AND		InvoiceID		=	@EscrowID
			AND		InvoiceType		=	2	--	Escrow Rollback
			AND		(
						(	PostID	IS NULL		)
						OR
						(	PostID	IS NOT NULL
							AND	PostID	= @PostID	)
					);
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to update auction delivery receipt; there is no such delivery id or post id is not same, escrowId:0x%I64X, deliveryId:0x%I64X, postId:0x%I64X', 16, @ERR_FAILURE,
																															@EscrowID, @DeliveryID, @PostID);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

