-- ===========================================================
-- Title		:	usp_FinishCharacterCreation
-- (author line removed)
-- Create date	:	2012-02-08
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_FinishCharacterCreation
(
	@PCID										BIGINT,
	@Job										SMALLINT,
	@Level										SMALLINT,
	@JumpingCharacterState						TINYINT,
	@IsConsumptionJumpingCharacterCreationQuota	BIT,
	@ShowcaseData								VARBINARY(4096)
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(		ISNULL(@PCID,								-1) <= 0
				OR	ISNULL(@Job,								-1) <= 0
				OR	ISNULL(@Level,								-1) <= 0
				OR	@JumpingCharacterState							IS NULL
				OR	@IsConsumptionJumpingCharacterCreationQuota		IS NULL
				OR	@ShowcaseData									IS NULL
				OR	DATALENGTH(@ShowcaseData)						<= 0
			)
			RAISERROR(N'invalid parameter, pcId:0x%I64X, job:%d, level:%d', 16, @ERR_FAILURE, @PCID, @Job, @Level);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE @gameAccountID	UNIQUEIDENTIFIER,
					@creationQuota	TINYINT			= 0,
					@creationCount	TINYINT			= 0;
			
			UPDATE	dbo.[Character]
			SET		@gameAccountID		= GameAccountID,
					Job					= @Job,
					[Level]				= @Level,
					CharacterState		= 2,	-- Creation Completion
					LastStateUpdateTime	= GETDATE(),
					JumpingCharacterState	= @JumpingCharacterState,
					CreationLevel		= @Level
			WHERE	PCID				= @PCID
			AND		CharacterState		= 1;	-- Creation Try
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'no such character, pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
			
			INSERT INTO dbo.CharacterData(
				PCID,
				ShowcaseData
			)
			VALUES (
				@PCID,
				@ShowcaseData
			);
			
			DECLARE	@ret		INT		= @ERR_FAILURE,
					@eventType	TINYINT	= 1;	-- Birth
			EXEC	@ret = dbo.usp_RegisterCharacterStory	@PCID, @eventType;
			IF	(@ret != @ERR_SUCCESS)
				RAISERROR(N'failed to register character story, pcId:0x%I64X, eventType:%d', 16, @ERR_FAILURE, @PCID, @eventType);

			IF @IsConsumptionJumpingCharacterCreationQuota = 1
			BEGIN
				UPDATE	dbo.JumpingCharacterCreationQuota
				SET		@creationQuota	=	CreationQuota,
						@creationCount	=	CreationCount + 1,
						CreationCount	+=	1
				WHERE	GameAccountID =		@gameAccountID;
				IF	(@@ROWCOUNT != 1)
				RAISERROR(N'no such jumping character creation quota, pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
				
				IF	(@creationQuota < @creationCount)
				RAISERROR(N'createCount is over creation quota , pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

usp_FinishCharacterDeletion.definition:
-- ===========================================================
-- Title		:	usp_FinishCharacterDeletion
-- (author line removed)
-- Create date	:	2012-02-08
-- Description	:	DeletionDelayDuration이 0이면 즉시 삭제
-- ===========================================================
CREATE PROCEDURE dbo.usp_FinishCharacterDeletion
(
	@PCID					BIGINT,
	@DeletionDelayDuration	INT,
	@DeletionDelayTime		DATETIME	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@DeletionDelayTime	= NULL;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@PCID, -1) <= 0
				OR	ISNULL(@DeletionDelayDuration, -1) < 0	)
			RAISERROR(N'invalid parameter, pcId:0x%I64X, deletionDelayDuration:%d', 16, @ERR_FAILURE, @PCID, @DeletionDelayDuration);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@currentTime	DATETIME = GETDATE();
			
			IF	(@DeletionDelayDuration = 0)	BEGIN
				-- 즉시 삭제
				UPDATE	dbo.[Character]
				SET		CharacterState		= 6,	-- Deletion Completion
						LastStateUpdateTime	= @currentTime
				WHERE	PCID				= @PCID
				AND		CharacterState		= 3;	-- Deletion Try
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'no such character, pcId:0x%I64X', 16, @ERR_FAILURE, @PCID);
				
				DECLARE	@ret		INT		= @ERR_FAILURE,
						@eventType	TINYINT	= 2;	-- Death
				EXEC	@ret = dbo.usp_RegisterCharacterStory	@PCID, @eventType;
				IF	(@ret != @ERR_SUCCESS)
					RAISERROR(N'failed to register character story, pcId:0x%I64X, eventType:%d', 16, @ERR_FAILURE, @PCID, @eventType);
				END
			ELSE	BEGIN
				-- 삭제 대기
				SET	@DeletionDelayTime	= DATEADD(SECOND, @DeletionDelayDuration, @currentTime);
				
				UPDATE	dbo.[Character]
				SET		CharacterState		= 4,	-- Deletion Waiting
						LastStateUpdateTime	= @currentTime,
