-- ===========================================================
-- Title		:	usp_FinishMileageDeposit
-- (author line removed)
-- Create date	:	2014-10-14
-- Description	:	
-- ===========================================================
CREATE PROC dbo.usp_FinishMileageDeposit
(
	  @MileageDepositID		BIGINT,
	  @Result				BIT			--	0:failure, 1:success
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		DECLARE	@resultStr NCHAR(1) = CAST(@Result AS NCHAR(1));
		
		-- Parameter validity check
		IF	(ISNULL(@MileageDepositID, -1) <= 0 OR @Result IS NULL)
			RAISERROR(N'invalid parameter, mileageDepositId:0x%I64X, result:%s', 16, @ERR_FAILURE, @MileageDepositID, @resultStr);

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN

		BEGIN
			IF	(@Result = 1)
			BEGIN
				DELETE	dbo.MileageDeposit
				WHERE	MileageDepositID = @MileageDepositID
				AND		DepositState IN(1, 3);
			END
			ELSE
			BEGIN
				UPDATE	dbo.MileageDeposit
				SET		DepositState = 2, DepositStateModificationTime = GETDATE()
				WHERE	MileageDepositID = @MileageDepositID
				AND		DepositState IN(1, 3);
			END
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to finish mileage deposit, mileageDepositId:0x%I64X, result:%s', 16, @ERR_FAILURE, @MileageDepositID, @resultStr);
		END

		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

