		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@ret	INT = @ERR_FAILURE;
			
			DECLARE @GameAccountIDString NVARCHAR(100) = CAST(@GameAccountID AS NVARCHAR(100))
			
			IF	(@GameAccountID IS NULL
					OR ISNULL(@AccountExp, -1) < 0
					OR ISNULL(@AccountExpPerDay, -1) < 0
					OR ISNULL(@LastUpdateTime, -1) < 0)	
				RAISERROR(N'invalid parameter, accountId:%s, accountExp:0x%I64X, accountExpPerDay:%d, lastUpdateTime:0x%I64X', 16, @ERR_FAILURE, 
				@GameAccountIDString, @AccountExp, @AccountExpPerDay, @LastUpdateTime);
			
			INSERT INTO dbo.GameAccountExp (
				GameAccountID,
				AccountExp,
				AccountExpQuotaPerDay,
				LastUpdateTime
			)
			VALUES	(
				@GameAccountID,
				@AccountExp,
				@AccountExpPerDay,
				@LastUpdateTime
			);
			
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'failed to insert account exp, accountId:%s, accountExp:0x%I64X, accountExpPerDay:%d, lastUpdateTime:0x%I64X', 16, @ERR_FAILURE, 
				@GameAccountIDString, @AccountExp, @AccountExpPerDay, @LastUpdateTime);
			
		END
		
		IF	(@INIT_TRANCOUNT = 0)	
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

