CREATE PROCEDURE [dbo].[usp_LoadGameAccountTimeBasedPlayInfo]
(
	@GameAccountID	UNIQUEIDENTIFIER
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	DECLARE @TARGET_TYPE_ALL	INT = 0,
			@TARGET_TYPE_PCCAFE	INT = 1;
			
	DECLARE @today				DATETIME = GETDATE()
	DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36));
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	@GameAccountID IS NULL	)	
		BEGIN
			--RAISERROR(N'invalid parameter1, gameAccountId:%s, target:%d, accType:%d', 16, @ERR_FAILURE, @gameAccountIdStr, @TargetType, @AccType);
			RAISERROR(N'invalid parameter1, gameAccountId:%s', 16, @ERR_FAILURE, @gameAccountIdStr);
		END
		
		-- 만료된 것들은 초기화 한다.
		-- 1. 날짜가 지난 경우
		-- (제거:ResetHour를 NP로 부터 받기 때문에) 2. TargetType이 ALL (daily reset) 인데 오늘 날짜가 아닌 경우
		BEGIN
			
			UPDATE	dbo.GameAccountTimeBasedPlayInfo
			SET		ScheduleNumber			= 0,
					ExpireTime				= 0,
					Duration				= 0,
					lastUpdate				= 0
			WHERE	GameAccountID			= @GameAccountID
				AND ScheduleNumber <> 0
				AND	(
					(ExpireTime < @today) 
					--OR 
					--(TargetType = @TARGET_TYPE_ALL AND 0 <> CONVERT(INT, DATEDIFF(DAY, lastUpdate , @today)))
				)			
		END
				
		-- 없는 경우라면 생성한다.
		BEGIN 
			-- ALL
			MERGE INTO dbo.GameAccountTimeBasedPlayInfo AS t1 USING	 (
				SELECT @GameAccountID AS GameAccountID, @TARGET_TYPE_ALL AS TargetType) AS t2
				ON (t1.GameAccountID = t2.GameAccountId AND t1.TargetType = t2.TargetType)
				WHEN NOT MATCHED THEN
					INSERT (GameAccountID, TargetType, ScheduleNumber, ExpireTime, Duration, LastUpdate) VALUES (t2.GameAccountId, t2.TargetType, 0, 0, 0, GETDATE());
			-- PCCAFE
			MERGE INTO dbo.GameAccountTimeBasedPlayInfo AS t1 USING	 (
				SELECT @GameAccountID AS GameAccountID, @TARGET_TYPE_PCCAFE AS TargetType) AS t2
				ON (t1.GameAccountID = t2.GameAccountId AND t1.TargetType = t2.TargetType)
				WHEN NOT MATCHED THEN
					INSERT (GameAccountID, TargetType, ScheduleNumber, ExpireTime, Duration, LastUpdate) VALUES (t2.GameAccountId, t2.TargetType, 0, 0, 0, GETDATE());
		END
							
		BEGIN
			SELECT	--GameAccountID,
					ScheduleNumber,
					TargetType,
					ExpireTime,
					Duration,
					LastUpdate
			FROM GameAccountTimeBasedPlayInfo
			WHERE GameAccountID = @GameAccountID
		END
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
