-- (author line removed)
-- Create date	:	2014-10-14
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_LoadMileage
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
			
		BEGIN
			DECLARE	@currentDate	DATETIME = GETDATE();
			
			UPDATE	dbo.Mileage
			SET		IsActivated = 0
			WHERE	IsActivated = 1
			
			UPDATE	dbo.Mileage
			SET		IsActivated = 1,
					FirstActivatedTime = CASE WHEN FirstActivatedTime IS NULL THEN @currentDate ELSE FirstActivatedTime END
			OUTPUT	inserted.MileageID, inserted.MileageName, inserted.MileageDescription, inserted.MileagePolicyID, inserted.EffectiveStartTime,
					inserted.EffectiveEndTime, inserted.AccumulateEndTime, inserted.AccumulateFrequencyType, inserted.AccumulateFrequency,
					inserted.MileageVirtualCurrencyID, inserted.MileageVirtualCurrencyAmount, inserted.MileageVirtualCurrencyExpireTime,
					inserted.AccumulateMinuteLimitPerDay, inserted.AccumulateLimitStandardHour
			WHERE	EffectiveStartTime <= @currentDate AND EffectiveEndTime	> @currentDate AND EndTime IS NULL;
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
