	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		-- Parameter validity check
		IF	(		@GameAccountID	IS NULL
				OR	ISNULL(@MileageID_1,	-1)	<= 0
				OR	(@MileageID_2	IS NOT NULL AND @MileageID_2	<= 0)
				OR	(@MileageID_3	IS NOT NULL AND @MileageID_3	<= 0)
				OR	(@MileageID_4	IS NOT NULL AND @MileageID_4	<= 0)
				OR	(@MileageID_5	IS NOT NULL AND @MileageID_5	<= 0)
				OR	(@MileageID_6	IS NOT NULL AND @MileageID_6	<= 0)
				OR	(@MileageID_7	IS NOT NULL AND @MileageID_7	<= 0)
				OR	(@MileageID_8	IS NOT NULL AND @MileageID_8	<= 0)
				OR	(@MileageID_9	IS NOT NULL AND @MileageID_9	<= 0)
				OR	(@MileageID_10	IS NOT NULL AND @MileageID_10	<= 0)	)
		BEGIN
			DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36));
			RAISERROR(N'invalid parameter, gameAccountId:%s', 16, @ERR_FAILURE, @gameAccountIdStr);
		END
		
		BEGIN
			SELECT	MileageAccumulatedTimePerDay.GameAccountID, MileageAccumulatedTimePerDay.MileageID,
					MileageAccumulatedTimePerDay.EffectiveEndTime, MileageAccumulatedTimePerDay.AccumulateMinute
			FROM	(	SELECT @GameAccountID AS GameAccountID, MileageID
						FROM	(VALUES	(@MileageID_1), (@MileageID_2), (@MileageID_3), (@MileageID_4), (@MileageID_5),
										(@MileageID_6), (@MileageID_7), (@MileageID_8), (@MileageID_9),(@MileageID_10)) AS MileageList(MileageID)
						WHERE MileageID IS NOT NULL
					) AS AccountMileageList
				INNER JOIN	dbo.MileageAccumulatedTimePerDay WITH(INDEX(PK_MileageAccumulatedTimePerDay))
						ON	AccountMileageList.MileageID = MileageAccumulatedTimePerDay.MileageID
						AND	AccountMileageList.GameAccountID = MileageAccumulatedTimePerDay.GameAccountID
			WHERE	MileageAccumulatedTimePerDay.EffectiveEndTime > GETDATE();
		END

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
