-- ===========================================================
-- Title		:	usp_LoadRandomStoreInitializationSchedule
-- (author line removed)
-- Create date	:	2014-03-20
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_LoadRandomStoreInitializationSchedule
(
	@CurrentScheduleNumber					BIGINT		OUTPUT,	
	@SlotCountInitScheduleNumber			BIGINT		OUTPUT,
	@PremiumDrawCountInitScheduleNumber		BIGINT		OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@CurrentScheduleNumber				= 0
	SET	@SlotCountInitScheduleNumber		= 0
	SET	@PremiumDrawCountInitScheduleNumber	= 0
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@oldScheduleNumber					BIGINT	= 0,
					@newScheduleNumber					BIGINT	= 0;
			
			SELECT	@oldScheduleNumber	= ScheduleNumber
			FROM	dbo.RandomStoreInitializationSchedule
			WITH	(TABLOCKX, INDEX(IX_RandomStoreInitializationSchedule_UniqueCurrentSchedule))
			WHERE	CurrentSchedule		= 1;
			
			SELECT	TOP(1)
					@newScheduleNumber	= ScheduleNumber
			FROM	dbo.RandomStoreInitializationSchedule
			WITH	(TABLOCKX, INDEX(UK_RandomStoreInitializationSchedule_ScheduleStartTime))
			WHERE	ScheduleStartTime	<= GETDATE()
			ORDER BY ScheduleStartTime	DESC;
						
			IF (@oldScheduleNumber != @newScheduleNumber)	BEGIN
				UPDATE	dbo.RandomStoreInitializationSchedule
				SET		CurrentSchedule	=	CASE
												WHEN	ScheduleNumber	= @oldScheduleNumber	THEN	0
												WHEN	ScheduleNumber	= @newScheduleNumber	THEN	1
											END
				WHERE	ScheduleNumber	IN	(@oldScheduleNumber, @newScheduleNumber);
			END
			
			SET	@CurrentScheduleNumber	= @newScheduleNumber;

			SELECT	TOP(1)
