	@GameAccountID_23	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_24	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_25	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_26	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_27	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_28	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_29	UNIQUEIDENTIFIER	= NULL,
	@GameAccountID_30	UNIQUEIDENTIFIER	= NULL
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	COALESCE(
							@GameAccountID_1,	@GameAccountID_2,	@GameAccountID_3,	@GameAccountID_4,	@GameAccountID_5,	@GameAccountID_6,	@GameAccountID_7,	@GameAccountID_8,	@GameAccountID_9,	@GameAccountID_10,
							@GameAccountID_11,	@GameAccountID_12,	@GameAccountID_13,	@GameAccountID_14,	@GameAccountID_15,	@GameAccountID_16,	@GameAccountID_17,	@GameAccountID_18,	@GameAccountID_19,	@GameAccountID_20,
							@GameAccountID_21,	@GameAccountID_22,	@GameAccountID_23,	@GameAccountID_24,	@GameAccountID_25,	@GameAccountID_26,	@GameAccountID_27,	@GameAccountID_28,	@GameAccountID_29,	@GameAccountID_30
						)	IS NULL	)
			RAISERROR(N'invalid parameter', 16, @ERR_FAILURE);
		
		BEGIN
			SELECT	GameAccount.GameAccountID,
					[Character].PCID,
					[Character].WorldID,
					GameWorld.WorldName,
					[Character].Job,
					[Character].[Level],
					[Character].CharacterName,
					[Character].LastPlayEndTime
			FROM	(
						SELECT	GameAccountID, ST
						FROM	(
									VALUES
									(@GameAccountID_1, 1),
									(@GameAccountID_2, 2),
									(@GameAccountID_3, 3),
									(@GameAccountID_4, 4),
									(@GameAccountID_5, 5),
									(@GameAccountID_6, 6),
									(@GameAccountID_7, 7),
									(@GameAccountID_8, 8),
									(@GameAccountID_9, 9),
									(@GameAccountID_10, 10),
									(@GameAccountID_11, 11),
									(@GameAccountID_12, 12),
									(@GameAccountID_13, 13),
									(@GameAccountID_14, 14),
									(@GameAccountID_15, 15),
									(@GameAccountID_16, 16),
									(@GameAccountID_17, 17),
									(@GameAccountID_18, 18),
									(@GameAccountID_19, 19),
									(@GameAccountID_20, 20),
									(@GameAccountID_21, 21),
									(@GameAccountID_22, 22),
									(@GameAccountID_23, 23),
									(@GameAccountID_24, 24),
									(@GameAccountID_25, 25),
									(@GameAccountID_26, 26),
									(@GameAccountID_27, 27),
									(@GameAccountID_28, 28),
									(@GameAccountID_29, 29),
									(@GameAccountID_30, 30)
								)	Parameter	(	GameAccountID, ST	)
						WHERE	GameAccountID	IS NOT NULL
					)	Parameter
					INNER LOOP JOIN
					(
						SELECT	GameAccountID
						FROM	dbo.GameAccount
						WITH	(READUNCOMMITTED, FORCESEEK)
					)	GameAccount
					ON	GameAccount.GameAccountID	= Parameter.GameAccountID
					LEFT OUTER LOOP JOIN
					(
						SELECT	PCID,
								GameAccountID,
								WorldID,
								Job,
								[Level],
								CharacterName,
								CharacterState,
								LastPlayEndTime
						FROM	dbo.[Character]
						WITH	(READUNCOMMITTED, INDEX(IX_Character_GameAccountID_CharacterState))
					)	[Character]
					ON	[Character].GameAccountID	= GameAccount.GameAccountID
					AND	[Character].CharacterState	IN (2, 3, 4, 5)		-- Creation Completion, Deletion Try, Deletion Waiting, Restoration Try
					LEFT OUTER LOOP JOIN
					(
						SELECT	WorldID,
								WorldName
						FROM	dbo.GameWorld
						WITH	(READUNCOMMITTED, FORCESEEK)
					)	GameWorld
					ON	GameWorld.WorldID	= [Character].WorldID
					ORDER BY ST;
		END
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

