-- ===========================================================
CREATE PROCEDURE dbo.usp_RetrieveMileageDeposit
(
	  @MileageDepositID	BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;

	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);

		-- Parameter validity check
		IF	(ISNULL(@MileageDepositID, -1) <= 0)
			RAISERROR(N'invalid parameter, mileageDepositId:0x%I64X', 16, @ERR_FAILURE, @MileageDepositID);

		BEGIN
			SELECT	MileageDeposit.MileageDepositID, MileageDeposit.GameAccountID, MileageDeposit.MileageID, MileageDeposit.AccumulateStartTime, MileageDeposit.AccumulateEndTime,
					MileageDeposit.AccumulateAmount, Mileage.MileageVirtualCurrencyID, Mileage.MileageVirtualCurrencyExpireTime
			FROM	dbo.MileageDeposit WITH(INDEX(PK_MileageDeposit))
				INNER JOIN	dbo.Mileage WITH(INDEX(PK_Mileage))
						ON	MileageDeposit.MileageID = Mileage.MileageID
			WHERE	MileageDeposit.MileageDepositID = @MileageDepositID
			AND		MileageDeposit.DepositState IN(1, 3);
		END

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

