		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			UPDATE	dbo.GameAccount
			SET		RepresentativePCID	= @RepresentativePCID
			WHERE	GameAccountID		= @GameAccountID;
			IF	(@@ROWCOUNT != 1)
