				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

usp_TryAuctionEscrow.definition:
-- ===========================================================
-- Title		:	usp_TryAuctionEscrow
-- (author line removed)
-- Create date	:	2013-07-04
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryAuctionEscrow
(
	@RequestID			UNIQUEIDENTIFIER,
	@AccountID			UNIQUEIDENTIFIER,
	@WorldID			SMALLINT,
	@PCID				BIGINT,
	@GameMoneyAmount	BIGINT,
	@EscrowID			BIGINT		OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET		@EscrowID	= NULL;
	
	DECLARE	@INIT_TRANCOUNT			INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS			INT = 0,
			@ERR_FAILURE			INT = 1,
			@ERR_NO_SUCH_CHARACTER	INT = 2;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		DECLARE	@requestIdStr	NCHAR(36)	= CAST(@RequestID AS NCHAR(36)),
				@accountIdStr	NCHAR(36)	= CAST(@AccountID AS NCHAR(36));
		
		IF	(	@RequestID IS NULL
				OR	@AccountID IS NULL
				OR	ISNULL(@WorldID, -1) <= 0
				OR	ISNULL(@PCID, -1) <= 0
				OR	ISNULL(@GameMoneyAmount, -1) <= 0	)
			RAISERROR(N'invalid parameter, requestId:%s, accountId:%s, worldId:%d, pcId:0x%I64X, gameMoneyAmount:%I64d', 16, @ERR_FAILURE,
											@requestIdStr, @accountIdStr, @WorldID, @PCID, @GameMoneyAmount);
		
		DECLARE	@characterName	NVARCHAR(32)	= NULL;
		
		SELECT	@characterName	= CharacterName
		FROM	dbo.[Character]
		WHERE	PCID			= @PCID
		AND		GameAccountID	= @AccountID
		AND		WorldID			= @WorldID;
		IF	(@@ROWCOUNT = 0)
			RAISERROR(N'there is no such character, requestId:%s, accountId:%s, worldId:%d, pcId:0x%I64X', 16, @ERR_NO_SUCH_CHARACTER,
													@requestIdStr, @accountIdStr, @WorldID, @PCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@registrationTime	DATETIME	= GETDATE();
			
			INSERT INTO dbo.AuctionEscrow (
				RequestID,
				AccountID,
				WorldID,
				PCID,
				CharacterName,
				GameMoneyAmount,
				EscrowState,
				RegistrationTime,
				LastStateUpdateTime
			)
			VALUES (
				@RequestID,
				@AccountID,
				@WorldID,
				@PCID,
				@characterName,
				@GameMoneyAmount,
				1,	--	Withdrawal Ready
				@registrationTime,
				@registrationTime
			);
			SET	@EscrowID	= SCOPE_IDENTITY();
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

usp_TryAuctionEscrowRollback.definition:
-- ===========================================================
-- Title		:	usp_TryAuctionEscrowRollback
-- (author line removed)
-- Create date	:	2013-07-04
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryAuctionEscrowRollback
(
	@RequestID				UNIQUEIDENTIFIER,
	@EscrowID				BIGINT				OUTPUT,
	@RecipientAccountID		UNIQUEIDENTIFIER	OUTPUT,
	@RecipientWID			SMALLINT			OUTPUT,
	@RecipientPCID			BIGINT				OUTPUT,
	@RecipientName			NVARCHAR(32)		OUTPUT,
	@GameMoneyAmount		BIGINT				OUTPUT,
	@DeliveryID				BIGINT				OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SELECT	@EscrowID			= NULL,
			@RecipientAccountID	= NULL,
			@RecipientWID		= NULL,
			@RecipientPCID		= NULL,
			@RecipientName		= NULL,
			@GameMoneyAmount	= NULL,
			@DeliveryID			= NULL;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		DECLARE	@requestIdStr	NCHAR(36)	= CAST(@RequestID AS NCHAR(36));
		IF	(	@RequestID IS NULL	)
			RAISERROR(N'invalid parameter, requestId:%s', 16, @ERR_FAILURE, @requestIdStr);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@currEscrowState	TINYINT	= 0;
			
			SELECT	@EscrowID			= EscrowID,
					@RecipientAccountID	= AccountID,
					@RecipientWID		= WorldID,
					@RecipientPCID		= PCID,
					@RecipientName		= CharacterName,
					@GameMoneyAmount	= GameMoneyAmount,
					@currEscrowState	= EscrowState,
					@DeliveryID			= DeliveryID
			FROM	(
						SELECT	EscrowID,
								AccountID,
								WorldID,
								PCID,
								CharacterName,
								GameMoneyAmount,
								EscrowState
						FROM	dbo.AuctionEscrow
						WITH	(UPDLOCK, FORCESEEK)
						WHERE	RequestID	= @RequestID
						AND		EscrowState	IN (2, 3)	--	Withdrawal Completion, Restoration Ready
					)	Escrow
					LEFT OUTER LOOP JOIN
					(
						SELECT	DeliveryID,
								InvoiceID,
								InvoiceType
						FROM	dbo.AuctionDelivery
						WITH	(FORCESEEK)
					)	Delivery
					ON	Delivery.InvoiceID		= Escrow.EscrowID
					AND	Delivery.InvoiceType	= 2;	-- Escrow Rollback
			IF	(@@ROWCOUNT = 0)
				RAISERROR(N'failed to try auction escrow rollback; there is no request id or invalid escrow state, requestId:%s', 16, @ERR_FAILURE, @requestIdStr);
			
			IF	(@currEscrowState = 2)	BEGIN	--	Withdrawal Completion
				DECLARE	@currentTime	DATETIME	= GETDATE();
				
				UPDATE	dbo.AuctionEscrow
				SET		EscrowState			= 3,	--	Restoration Ready
						LastStateUpdateTime	= @currentTime
				WHERE	EscrowID			= @EscrowID
				AND		EscrowState			= 2;	--	Withdrawal Completion
				IF	(@@ROWCOUNT != 1)
					RAISERROR(N'failed to update escrow state to restoration ready state, requestId:%s, escrowId:0x%I64X', 16, @ERR_FAILURE, @requestIdStr, @EscrowID);
				
				INSERT INTO dbo.AuctionDelivery (
					InvoiceID,
					InvoiceType,
					RegistrationTime,
					LastUpdateTime,
					PostID
				)
				VALUES (
					@EscrowID,
					2,	--	Escrow Rollback
					@currentTime,
					@currentTime,
					NULL
				);
				SET	@DeliveryID	= SCOPE_IDENTITY();
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

usp_TryAuctionResultDelivery.definition:
-- ===========================================================
-- Title		:	usp_TryAuctionResultDelivery
-- (author line removed)
-- Create date	:	2013-07-04
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryAuctionResultDelivery
(
	@RequestID				NVARCHAR(50),
	@AuctionID				UNIQUEIDENTIFIER,
	@RecipientAccountID		UNIQUEIDENTIFIER,
	@RecipientWID			SMALLINT,
	@RecipientPCID			BIGINT,
	@DeliveryID				BIGINT			OUTPUT,
	@RecipientName			NVARCHAR(32)	OUTPUT,
	@PostID					BIGINT			OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SELECT	@DeliveryID		= NULL,
			@RecipientName	= NULL,
			@PostID			= NULL;
	
	DECLARE	@INIT_TRANCOUNT				INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS				INT = 0,
			@ERR_FAILURE				INT = 1,
			@ERR_NO_SUCH_CHARACTER		INT = 2,
			@ERR_ALREADY_DELIVERED		INT = 3;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		DECLARE	@auctionIdStr			NCHAR(36)	= CAST(@AuctionID AS NCHAR(36)),
				@recipientAccountIdStr	NCHAR(36)	= CAST(@RecipientAccountID AS NCHAR(36));
		
		IF	(	ISNULL(@RequestID, N'') = N''
				OR	@AuctionID IS NULL
				OR	@RecipientAccountID IS NULL
				OR	ISNULL(@RecipientWID, -1) <= 0
				OR	ISNULL(@RecipientPCID, -1) <= 0	)
			RAISERROR(N'invalid parameter, requestId:%s, auctionId:%s, recipientAccountId:%s, recipientWid:%d, recipientPcId:0x%I64X', 16, @ERR_FAILURE,
											@RequestID, @auctionIdStr, @recipientAccountIdStr, @RecipientWID, @RecipientPCID);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			SELECT	@DeliveryID		= DeliveryID,
					@RecipientName	= CharacterName,
					@PostID			= PostID
			FROM	(
						SELECT	AuctionResultID,
								CharacterName
						FROM	dbo.AuctionResult
						WITH	(FORCESEEK)
						WHERE	RequestID	= @RequestID
					)	Result
					INNER LOOP JOIN
					(
						SELECT	DeliveryID,
								InvoiceID,
								InvoiceType,
								PostID
						FROM	dbo.AuctionDelivery
						WITH	(FORCESEEK)
					)	Delivery
					ON	Delivery.InvoiceID		= Result.AuctionResultID
					AND	Delivery.InvoiceType	= 1;	--	Auction Result
			IF	(@@ROWCOUNT = 0)	BEGIN
				SELECT	@RecipientName	= CharacterName
				FROM	dbo.[Character]
				WHERE	PCID			= @RecipientPCID
				AND		GameAccountID	= @RecipientAccountID
				AND		WorldID			= @RecipientWID;
				IF	(@@ROWCOUNT = 0)
					RAISERROR(N'there is no such character, requestId:%s, auctionId:%s, recipientAccountId:%s, recipientWid:%d, recipientPcId:0x%I64X', 16, @ERR_NO_SUCH_CHARACTER,
															@RequestID, @auctionIdStr, @recipientAccountIdStr, @RecipientWID, @RecipientPCID);
				
				DECLARE	@registrationTime	DATETIME	= GETDATE(),
						@auctionResultId	BIGINT		= NULL;
				
				INSERT INTO dbo.AuctionResult (
					RequestID,
					AuctionID,
					PCID,
					CharacterName,
					RegistrationTime
				)
				VALUES (
					@RequestID,
					@AuctionID,
					@RecipientPCID,
					@RecipientName,
					@registrationTime
				);
				SET	@auctionResultId	= SCOPE_IDENTITY();
				
				INSERT INTO dbo.AuctionDelivery (
					InvoiceID,
					InvoiceType,
					RegistrationTime,
					LastUpdateTime,
					PostID
				)
				VALUES (
					@auctionResultId,
					1,	--	Auction Result
					@registrationTime,
					@registrationTime,
					NULL
				);
				SET	@DeliveryID	= SCOPE_IDENTITY();
			END
			ELSE	BEGIN
				IF	(@PostID IS NOT NULL)
					RAISERROR(N'already delivered auction result, requestId:%s, auctionId:%s, pcId:0x%I64X, deliveryId:0x%I64X, postId:0x%I64X', 16, @ERR_ALREADY_DELIVERED,
																	@RequestID, @auctionIdStr, @RecipientPCID, @DeliveryID, @PostID);
			END
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

