usp_TryCharacterCreation.definition:
-- ===========================================================
-- Title		:	usp_TryCharacterCreation
-- (author line removed)
-- Create date	:	2012-02-08
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryCharacterCreation
(
	@GameAccountID		UNIQUEIDENTIFIER,
	@SlotID				UNIQUEIDENTIFIER,
	@WorldID			SMALLINT,
	@CharacterName		NVARCHAR(32),
	@CharacterRight		TINYINT,
	@PCID				BIGINT	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@PCID = 0;
	
	DECLARE	@INIT_TRANCOUNT					INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS					INT = 0,
			@ERR_FAILURE					INT = 1,
			@ERR_DUPLICATED_CHARACTER_NAME	INT = 2,
			@ERR_LIMITED_CHARACTER_NAME		INT = 3;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	@GameAccountID IS NULL
				OR	@SlotID IS NULL
				OR	ISNULL(@WorldID, -1) <= 0
				OR	ISNULL(@CharacterName, N'') = N''
				OR	ISNULL(@CharacterRight, 0) = 0	)	BEGIN
			DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36)),
					@slotIdStr			NCHAR(36) = CAST(@SlotID AS NCHAR(36));
			RAISERROR(N'invalid parameter, gameAccountId:%s, slotId:%s, worldId:%d, characterName:%s, characterRight:%d', 16, @ERR_FAILURE,
											@gameAccountIdStr, @slotIdStr, @WorldID, @CharacterName, @CharacterRight);
		END
		
		DECLARE	@ret	INT = @ERR_FAILURE;
		EXEC	@ret = dbo.usp_CheckValidityOfCharacterName @CharacterName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'invalid character name, characterName:%s', 16, @ERR_FAILURE, @CharacterName);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@registrationTime	DATETIME = GETDATE();
			
			INSERT INTO dbo.[Character](
				GameAccountID,
				SlotID,
				WorldID,
				Job,
				[Level],
				CharacterName,
				PureCharacterName,
				CharacterRight,
				CharacterState,
				RegistrationTime,
				LastStateUpdateTime,
				DeletionDelayTime,
				LastPlayStartTime,
				LastPlayEndTime,
				LastPlayIPv4Address,
				JumpingCharacterState,
				CreationLevel
			)
			VALUES (
				@GameAccountID,
				@SlotID,
				@WorldID,
				NULL,
				NULL,
				@CharacterName,
				dbo.ufn_GetPureName(@CharacterName),
				@CharacterRight,
				1,	-- Creation Try
				@registrationTime,
				@registrationTime,
				NULL,
				NULL,
				NULL,
				NULL,
				0,
				NULL
			);
			SET	@PCID = SCOPE_IDENTITY();
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
			ELSE	BEGIN
				IF	(@ERR_PROCEDURE = N'usp_CheckValidityOfCharacterName')	BEGIN
					SELECT	@ERR_CODE	=	CASE	@ERR_STATE	WHEN	2	THEN	@ERR_DUPLICATED_CHARACTER_NAME
																WHEN	3	THEN	@ERR_LIMITED_CHARACTER_NAME
																ELSE				@ERR_FAILURE	END
				END
			END
		END
		ELSE IF (@ERR_NUMBER = 2601)
			SET	@ERR_CODE = @ERR_DUPLICATED_CHARACTER_NAME;
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

