		EXEC	@ret = dbo.usp_CheckValidityOfCharacterName @NewCharacterName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'invalid character name, newCharacterName:%s', 16, @ERR_FAILURE, @NewCharacterName);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@serviceType	TINYINT	= 3;	-- Character Rename Service
			
			EXEC	@ret = dbo.usp_RegisterLobbyService		@GameAccountID,
															@serviceType,
															@ItemInstanceID,
															@ItemDataID,
															@ServiceID	OUTPUT;
			IF	(@ret != @ERR_SUCCESS)
				RAISERROR(N'failed to register lobby service, gameAccountId:%s, pcId:0x%I64X, itemInstanceId:0x%I64X, itemDataId:%d, newCharacterName:%s, reuseLimitDuration:%d', 16, @ERR_FAILURE,
															@gameAccountIdStr, @PCID, @ItemInstanceID, @ItemDataID, @NewCharacterName, @ReuseLimitDuration);
			
			DECLARE	@oldData	TABLE
			(
				OldCharacterName		NVARCHAR(32)	NOT NULL,
				OldPureCharacterName	NVARCHAR(32)	NOT NULL
			);
			DECLARE	@registrationTime	DATETIME = GETDATE();		
			DECLARE	@reuseLimitTime		DATETIME = DATEADD(SECOND, @ReuseLimitDuration, @registrationTime);
			
			UPDATE	dbo.[Character]
			SET		CharacterName		= @NewCharacterName,
					PureCharacterName	= dbo.ufn_GetPureName(@NewCharacterName)
			OUTPUT	DELETED.CharacterName,
					DELETED.PureCharacterName
			INTO	@oldData
			WHERE	PCID			= @PCID
			AND		CharacterState	= 2;	-- Creation Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'no such character, gameAccountId:%s, pcId:0x%I64X, itemInstanceId:0x%I64X, itemDataId:%d, newCharacterName:%s, reuseLimitDuration:%d', 16, @ERR_FAILURE,
												@gameAccountIdStr, @PCID, @ItemInstanceID, @ItemDataID, @NewCharacterName, @ReuseLimitDuration);
			
			INSERT INTO dbo.CharacterRename(
				ServiceID,
				PCID,
				OldCharacterName,
				OldPureCharacterName,
				NewCharacterName,
				NewPureCharacterName,
				RenameState,
				RegistrationTime,
				LastStateUpdateTime,
				ReuseLimitTime
			)
			SELECT	@ServiceID,
					@PCID,
					OldCharacterName,
					OldPureCharacterName,
					@NewCharacterName,
					dbo.ufn_GetPureName(@NewCharacterName),
					1,	-- Rename Try
					@registrationTime,
					@registrationTime,
					@reuseLimitTime
			FROM	@oldData;
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
			ELSE	BEGIN
				IF	(@ERR_PROCEDURE = N'usp_CheckValidityOfCharacterName')	BEGIN
					SELECT	@ERR_CODE	=	CASE	@ERR_STATE	WHEN	2	THEN	@ERR_DUPLICATED_CHARACTER_NAME
																WHEN	3	THEN	@ERR_LIMITED_CHARACTER_NAME
																ELSE				@ERR_FAILURE	END
				END
			END
		END
		ELSE IF (@ERR_NUMBER = 2601)
			SET	@ERR_CODE = @ERR_DUPLICATED_CHARACTER_NAME;
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

