CREATE PROCEDURE dbo.usp_TryGuildRegistration
(
	@WorldClusterID	SMALLINT,
	@WorldID		SMALLINT,
	@GuildType		TINYINT,
	@GuildName		NVARCHAR(32),
	@GuildID		BIGINT	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@GuildID = 0;
	
	DECLARE	@INIT_TRANCOUNT				INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS				INT = 0,
			@ERR_FAILURE				INT = 1,
			@ERR_DUPLICATED_GUILD_NAME	INT = 2,
			@ERR_LIMITED_GUILD_NAME		INT = 3;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@WorldClusterID, -1) <= 0
				OR	ISNULL(@WorldID, -1) <= 0
				OR	ISNULL(@GuildName, N'') = N''	)
			RAISERROR(N'invalid parameter, worldClusterId:%d, worldId:%d, guildName:%s', 16, @ERR_FAILURE, @WorldClusterID, @WorldID, @GuildName);
			
		DECLARE	@ret	INT = @ERR_FAILURE;
