		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@registrationTime	DATETIME = GETDATE();
			
			INSERT INTO dbo.GuildRegistry (
				WorldClusterID,
				WorldID,
				GuildType,
				GuildName,
				PureGuildName,
				GuildState,
				RegistrationTime,
				LastStateUpdateTime,
				ReuseLimitTime
