usp_TryMileageDeposit.definition:
-- ===========================================================
-- Title		:	usp_TryMileageDeposit
-- (author line removed)
-- Create date	:	2014-10-14
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryMileageDeposit
(
	--MileageDeposit
	  @GameAccountID		UNIQUEIDENTIFIER
	, @MileageID			INT
	, @AccumulateStartTime	DATETIME
	, @AccumulateEndTime	DATETIME
	, @AccumulateAmount		BIGINT
	--MileageAccumulatedTimePerDay
	, @EffectiveEndTime		DATETIME
	, @AccumulateMinute		SMALLINT
	, @MileageDepositID		BIGINT				OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;

	SET		@MileageDepositID		= 0;

	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		DECLARE	@gameAccountIdStr		NCHAR(36)	= CAST(@GameAccountID AS NCHAR(36)),
				@accumulateStartTimeStr	NCHAR(23)	= CONVERT(NCHAR(23), @AccumulateStartTime, 121),
				@accumulateEndTimeStr	NCHAR(23)	= CONVERT(NCHAR(23), @AccumulateEndTime, 121),
				@effectiveEndTimeStr	NCHAR(23)	= CONVERT(NCHAR(23), @EffectiveEndTime, 121),
				@rowcount				INT			= 0;
		
		-- Parameter validity check
		IF	(		@GameAccountID								IS NULL
				OR	ISNULL(@MileageID, -1)						<= 0
				OR	ISNULL(@AccumulateStartTime, N'1970-01-01')	= N'1970-01-01'
				OR	ISNULL(@AccumulateEndTime, N'1970-01-01')	= N'1970-01-01'
				OR	@AccumulateStartTime						> @AccumulateEndTime
				OR	ISNULL(@AccumulateAmount, -1)				<= 0
				OR  (@AccumulateMinute IS NOT NULL	AND @EffectiveEndTime IS NULL)
				OR  (@AccumulateMinute IS NULL		AND @EffectiveEndTime IS NOT NULL)		)
		BEGIN
			RAISERROR(	N'invalid parameter, gameAccountId:%s, mileageId:%d, accumulateStartTime:%s, accumulateEndTime:%s, accumulateAmount:0x%I64X, accumulateMinute:%d, effectiveEndTime:%s',
						16, @ERR_FAILURE,
						@gameAccountIdStr, @MileageID, @accumulateStartTimeStr, @accumulateEndTimeStr, @AccumulateAmount, @AccumulateMinute, @effectiveEndTimeStr);
		END

		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN

		BEGIN
			IF	(@AccumulateMinute IS NOT NULL AND @EffectiveEndTime IS NOT NULL)
			BEGIN
				MERGE	dbo.MileageAccumulatedTimePerDay AS Target
				USING	(VALUES(@GameAccountID, @MileageID, @EffectiveEndTime, @AccumulateMinute)) AS Source(GameAccountID, MileageID, EffectiveEndTime, AccumulateMinute)
						ON Target.GameAccountID = Source.GameAccountID AND Target.MileageID = Source.MileageID
				WHEN MATCHED THEN
					UPDATE SET	EffectiveEndTime = CASE WHEN Target.EffectiveEndTime != Source.EffectiveEndTime THEN Source.EffectiveEndTime ELSE Target.EffectiveEndTime END,
								AccumulateMinute = Source.AccumulateMinute
				WHEN NOT MATCHED THEN
					INSERT	(GameAccountID, MileageID, EffectiveEndTime, AccumulateMinute)
					VALUES	(Source.GameAccountID, Source.MileageID, Source.EffectiveEndTime, Source.AccumulateMinute);
				IF	(@@ROWCOUNT != 1)
				BEGIN
					RAISERROR(	N'failed to try accumulate minute, gameAccountId:%s, mileageId:%d, accumulateMinute:%d, effectiveEndTime:%s',
								16, @ERR_FAILURE,
								@gameAccountIdStr, @MileageID, @accumulateStartTimeStr, @effectiveEndTimeStr);
				END
			END
			
			INSERT	dbo.MileageDeposit
					(GameAccountID, MileageID, AccumulateStartTime, AccumulateEndTime, AccumulateAmount, DepositState, DepositStateModificationTime)
			VALUES	(@GameAccountID, @MileageID, @AccumulateStartTime, @AccumulateEndTime, @AccumulateAmount, 1, GETDATE());
			SELECT	@rowcount = @@ROWCOUNT, @MileageDepositID = SCOPE_IDENTITY();
			IF	(@rowcount != 1 OR @MileageDepositID < 1)
			BEGIN
				RAISERROR(	N'failed to try mileage deposit, mileageDepositId:0x%I64X, gameAccountId:%s, mileageId:%d, accumulateStartTime:%s, accumulateEndTime:%s, accumulateAmount:0x%I64X',
							16, @ERR_FAILURE,
							@MileageDepositID, @gameAccountIdStr, @MileageID, @accumulateStartTimeStr, @accumulateEndTimeStr, @AccumulateAmount);
			END
		END

		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;

		RETURN @ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END

		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;

		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END

		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);

		RETURN @ERR_CODE;
	END CATCH
END

usp_TryRenameGuild.definition:
-- ===========================================================
-- Title		:	usp_TryRenameGuild
-- (author line removed)
-- Create date	:	2012-02-08
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_TryRenameGuild
(
	@GuildID				BIGINT,
	@RenameGuildType		INT,
	@NewGuildName			NVARCHAR(32),
	@ReuseLimitDuration		INT,
	@RenameKey				BIGINT	OUTPUT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	SET	@RenameKey = 0;
	
	DECLARE	@INIT_TRANCOUNT				INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS				INT = 0,
			@ERR_FAILURE				INT = 1,
			@ERR_DUPLICATED_GUILD_NAME	INT = 2,
			@ERR_LIMITED_GUILD_NAME		INT = 3,
			@ERR_ALREADY_IN_TRY_STATE	INT = 4;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'rename-guild; invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		-- Parameter validity check
		IF	(	ISNULL(@GuildID, -1) <= 0 
				OR	ISNULL(@NewGuildName, N'') = N''
				OR	ISNULL(@ReuseLimitDuration, -1) < 0	)
			RAISERROR(N'rename-guild; invalid parameter, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_FAILURE, @GuildID, @NewGuildName, @ReuseLimitDuration);
		
		DECLARE	@ret	INT = @ERR_FAILURE;
		EXEC	@ret = dbo.usp_CheckValidityOfGuildName @NewGuildName;
		IF	(@ret != @ERR_SUCCESS)
			RAISERROR(N'rename-guild; invalid guild name, newGuildName:%s', 16, @ERR_FAILURE, @NewGuildName);
		
		IF	EXISTS	(	SELECT	1
						FROM	dbo.GuildRename
						WHERE	GuildID		= @GuildID
						AND		RenameState	= 1		-- Rename Try
					)
			RAISERROR(N'rename-guild; already in try state, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_ALREADY_IN_TRY_STATE, @GuildID, @NewGuildName, @ReuseLimitDuration);
		
		DECLARE	@data	TABLE
		(
			GuildID				BIGINT			NOT NULL,
			OldGuildName		NVARCHAR(32)	NOT NULL,
			OldPureGuildName	NVARCHAR(32)	NOT NULL
		);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@registrationTime	DATETIME = GETDATE();		
			DECLARE	@reuseLimitTime		DATETIME = DATEADD(SECOND, @ReuseLimitDuration, @registrationTime);
			
			UPDATE	dbo.GuildRegistry
			SET		GuildName		= @NewGuildName,
					PureGuildName	= dbo.ufn_GetPureName(@NewGuildName)
			OUTPUT	@GuildID,
					DELETED.GuildName,
					DELETED.PureGuildName
			INTO	@data
			WHERE	GuildID		= @GuildID
			AND		GuildState	= 2;	-- Creation Completion
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'rename-guild; no such guild, guild-id:0x%I64x, new-guild-name:%s, reuse-limit-duration:%d', 16, @ERR_FAILURE, @GuildID, @NewGuildName, @ReuseLimitDuration);
			
			INSERT INTO dbo.GuildRename (
				GuildID,
				RenameGuildType,
				OldGuildName,
				OldPureGuildName,
				NewGuildName,
				NewPureGuildName,
				RenameState,
				RegistrationTime,
				LastStateUpdateTime,
				ReuseLimitTime
			)
			SELECT	GuildID,
					@RenameGuildType,
					OldGuildName,
					OldPureGuildName,
					@NewGuildName,
					dbo.ufn_GetPureName(@NewGuildName),
					1,	-- Rename Try
					@registrationTime,
					@registrationTime,
					@reuseLimitTime
			FROM	@data;
			SET	@RenameKey = SCOPE_IDENTITY();
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
			ELSE	BEGIN
				IF	(@ERR_PROCEDURE = N'usp_CheckValidityOfGuildName')	BEGIN
					SELECT	@ERR_CODE	=	CASE	@ERR_STATE	WHEN	2	THEN	@ERR_DUPLICATED_GUILD_NAME
																WHEN	3	THEN	@ERR_LIMITED_GUILD_NAME
																ELSE				@ERR_FAILURE	END
				END
			END
		END
		ELSE IF (@ERR_NUMBER = 2601)
			SET	@ERR_CODE = @ERR_DUPLICATED_GUILD_NAME;
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

