CREATE PROCEDURE dbo.usp_UpdateGameAccountContentQuota
(
	@GameAccountID		UNIQUEIDENTIFIER,
	@DataID				INT,
	@Version			SMALLINT,
	@Quantity			BIGINT,
	@LastUpdateTime		BIGINT
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT	= 0,
			@ERR_FAILURE		INT	= 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			MERGE	dbo.GameAccountContentQuota AS Target
			USING	(	VALUES(@GameAccountID, @DataID, @Version, @Quantity, @LastUpdateTime)
					)	AS Source (GameAccountID, DataID, [Version], Quantity, LastUpdateTime)
					ON	Target.GameAccountID = Source.GameAccountID AND Target.DataID = Source.DataID
			WHEN MATCHED THEN
				UPDATE
				SET		Target.[Version] = CASE WHEN Source.LastUpdateTime >= Target.LastUpdateTime THEN Source.[Version] ELSE Target.[Version] END,
						Target.Quantity = CASE WHEN Source.LastUpdateTime >= Target.LastUpdateTime THEN Source.Quantity ELSE Target.Quantity END,
						Target.LastUpdateTime = CASE WHEN Source.LastUpdateTime >= Target.LastUpdateTime THEN Source.LastUpdateTime ELSE Target.LastUpdateTime END
			WHEN NOT MATCHED THEN
				INSERT	(GameAccountID, DataID, [Version], Quantity, LastUpdateTime)
				VALUES	(@GameAccountID, @DataID, @Version, @Quantity, @LastUpdateTime);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
