				OR	ISNULL(@ServiceType, 0) = 0
				OR	ISNULL(@CurrentServiceState, 0) = 0	)
			RAISERROR(N'invalid parameter, serviceId:0x%I64X, gameAccountId:%s, serviceType:%d, currentServiceState:%d', 16, @ERR_FAILURE,
											@ServiceID, @gameAccountIdStr, @ServiceType, @CurrentServiceState);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			UPDATE	dbo.LobbyService
			SET		ServiceState		= @CurrentServiceState + 1,
					LastStateUpdateTime	= GETDATE()
			WHERE	ServiceID			= @ServiceID
			AND		GameAccountID		= @GameAccountID
			AND		ServiceType			= @ServiceType
			AND		ServiceState		= @CurrentServiceState;
			IF	(@@ROWCOUNT != 1)
				RAISERROR(N'no such lobby service, serviceId:0x%I64X, gameAccountId:%s, serviceType:%d, currentServiceState:%d', 16, @ERR_FAILURE,
													@ServiceID, @gameAccountIdStr, @ServiceType, @CurrentServiceState);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END

