-- ===========================================================
-- Title		:	usp_WriteUserRenameServiceLog
-- (author line removed)
-- Create date	:	2013-07-22
-- Description	:	
-- ===========================================================
CREATE PROCEDURE dbo.usp_WriteUserRenameServiceLog
(
	@GameAccountID		UNIQUEIDENTIFIER,
	@ItemInstanceID		BIGINT,
	@ItemDataID			INT,
	@OldUserName		NVARCHAR(64),
	@NewUserName		NVARCHAR(64)
)
AS
BEGIN
	SET NOCOUNT, XACT_ABORT ON;
	
	DECLARE	@INIT_TRANCOUNT		INT	= @@TRANCOUNT,
			-- Error Code
			@ERR_SUCCESS		INT = 0,
			@ERR_FAILURE		INT = 1;
	
	BEGIN TRY
		-- Transaction validity check
		IF	(@@NESTLEVEL = 1 AND @INIT_TRANCOUNT > 0)
			RAISERROR(N'invalid initial transaction, init trancount:%d', 16, @ERR_FAILURE, @INIT_TRANCOUNT);
		
		DECLARE	@gameAccountIdStr	NCHAR(36) = CAST(@GameAccountID AS NCHAR(36));
		-- Parameter validity check
		IF	(	@GameAccountID IS NULL
				OR	ISNULL(@ItemInstanceID, -1) <= 0
				OR	ISNULL(@ItemDataID, -1) <= 0
				OR	ISNULL(@OldUserName, N'') = N''
				OR	ISNULL(@NewUserName, N'') = N''	)
			RAISERROR(N'invalid parameter, gameAccountId:%s, itemInstanceId:0x%I64X, itemDataId:%d, oldUserName:%s, newUserName:%s', 16, @ERR_FAILURE,
											@gameAccountIdStr, @ItemInstanceID, @ItemDataID, @OldUserName, @NewUserName);
		
		IF	(@INIT_TRANCOUNT = 0)
			BEGIN TRAN
		
		BEGIN
			DECLARE	@ServiceID			BIGINT		= 0,
					@registrationTime	DATETIME	= GETDATE();
			
			INSERT INTO dbo.LobbyService (
				GameAccountID,
				ServiceType,
				ItemInstanceID,
				ItemDataID,
				ServiceState,
				RegistrationTime,
				LastStateUpdateTime
			)
			VALUES (
				@GameAccountID,
				4,		--	User Rename Service
				@ItemInstanceID,
				@ItemDataID,
				5,		--	Service Finish
				@registrationTime,
				@registrationTime
			);
			SET	@ServiceID	= SCOPE_IDENTITY();
			
			INSERT INTO dbo.UserRename (
				ServiceID,
				GameAccountID,
				OldUserName,
				NewUserName,
				RegistrationTime
			)
			VALUES (
				@ServiceID,
				@GameAccountID,
				@OldUserName,
				@NewUserName,
				@registrationTime
			);
		END
		
		IF	(@INIT_TRANCOUNT = 0)
			COMMIT;
		
		RETURN	@ERR_SUCCESS;
	END TRY
	BEGIN CATCH
		IF	(XACT_STATE() != 0 AND @INIT_TRANCOUNT = 0)	BEGIN
			ROLLBACK;
			EXEC dbo.usp_LogError;
		END
		
		DECLARE	@ERR_NUMBER		INT				= ERROR_NUMBER(),
				@ERR_SEVERITY	INT				= ERROR_SEVERITY(),
				@ERR_STATE		INT				= ERROR_STATE(),
				@ERR_PROCEDURE	NVARCHAR(126)	= ERROR_PROCEDURE(),
				@ERR_MESSAGE	NVARCHAR(2048)	= ERROR_MESSAGE(),
				@ERR_CODE		INT				= @ERR_FAILURE;
		
		IF	(@ERR_NUMBER >= 50000)	BEGIN
			IF	(@ERR_PROCEDURE = OBJECT_NAME(@@PROCID))
				SET	@ERR_CODE = @ERR_STATE;
		END
		
		IF	(@@NESTLEVEL = 1)
			RAISERROR(N'[%s], %s', @ERR_SEVERITY, @ERR_CODE, @ERR_PROCEDURE, @ERR_MESSAGE);
		ELSE
			RAISERROR(@ERR_MESSAGE, @ERR_SEVERITY, @ERR_CODE);
		
		RETURN	@ERR_CODE;
	END CATCH
END
